#!/usr/bin/env node

import * as fs from 'fs';
import * as readline from 'readline';
import { validateJson, formatJson, compactJson, analyzeJson } from './json-utils';

const args = process.argv.slice(2);
const command = args[0];
const options = args.slice(1);

async function readStdin(): Promise<string> {
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  return new Promise((resolve) => {
    let input = '';
    rl.on('line', (line) => {
      input += line + '\n';
    });
    rl.on('close', () => {
      resolve(input.trim());
    });
  });
}

function getInput(args: string[]): string {
  if (args.length > 0 && fs.existsSync(args[0])) {
    return fs.readFileSync(args[0], 'utf-8');
  }
  // For async stdin, we need to handle it differently
  return '';
}

async function main() {
  try {
    let input: string;

    // Read from file or stdin
    if (args.length > 0 && fs.existsSync(args[0])) {
      input = fs.readFileSync(args[0], 'utf-8');
    } else {
      input = await readStdin();
    }

    if (!input) {
      console.error('Error: No input provided');
      process.exit(1);
    }

    // Validate first
    const validation = validateJson(input);
    if (!validation.valid) {
      console.error(`❌ Invalid JSON: ${validation.error}`);
      process.exit(1);
    }

    // Process based on command
    switch (command) {
      case 'format':
      case undefined: {
        const indent = options.includes('--compact')
          ? undefined
          : parseInt(options[options.indexOf('--indent') + 1] || '2', 10);
        const formatted = indent ? formatJson(input, indent) : compactJson(input);
        console.log(formatted);
        break;
      }

      case 'compact': {
        const compact = compactJson(input);
        console.log(compact);
        break;
      }

      case 'analyze': {
        const stats = analyzeJson(input);
        console.log('📊 JSON Analysis:');
        console.log(`  Characters: ${stats.characterCount}`);
        console.log(`  Keys: ${stats.keyCount}`);
        console.log(`  Depth: ${stats.depth}`);
        console.log(`  Has Arrays: ${stats.hasArrays ? '✓' : '✗'}`);
        console.log(`  Has Objects: ${stats.hasObjects ? '✓' : '✗'}`);
        break;
      }

      case 'validate': {
        console.log('✅ Valid JSON');
        break;
      }

      default:
        console.error(`Unknown command: ${command}`);
        console.error('Commands: format, compact, analyze, validate');
        process.exit(1);
    }
  } catch (error) {
    console.error('Error:', error instanceof Error ? error.message : error);
    process.exit(1);
  }
}

main();

