import {
  validateJson,
  formatJson,
  compactJson,
  analyzeJson,
} from './json-utils';

describe('json-utils', () => {
  describe('validateJson', () => {
    it('should validate correct JSON', () => {
      const result = validateJson('{"key": "value"}');
      expect(result.valid).toBe(true);
    });

    it('should reject invalid JSON', () => {
      const result = validateJson('{invalid json}');
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
    });

    it('should validate arrays', () => {
      const result = validateJson('[1, 2, 3]');
      expect(result.valid).toBe(true);
    });
  });

  describe('formatJson', () => {
    it('should format JSON with default indentation', () => {
      const input = '{"a":1,"b":2}';
      const output = formatJson(input);
      expect(output).toContain('\n');
      expect(output).toContain('"a"');
    });

    it('should format with custom indentation', () => {
      const input = '{"a":1}';
      const output = formatJson(input, 4);
      expect(output.includes('    ')).toBe(true);
    });
  });

  describe('compactJson', () => {
    it('should compact formatted JSON', () => {
      const input = '{\n  "key": "value"\n}';
      const output = compactJson(input);
      expect(output).toBe('{"key":"value"}');
      expect(output.includes('\n')).toBe(false);
    });
  });

  describe('analyzeJson', () => {
    it('should analyze simple object', () => {
      const stats = analyzeJson('{"key": "value"}');
      expect(stats.characterCount).toBeGreaterThan(0);
      expect(stats.keyCount).toBe(1);
      expect(stats.depth).toBe(1);
      expect(stats.hasObjects).toBe(true);
      expect(stats.hasArrays).toBe(false);
    });

    it('should analyze nested structure', () => {
      const stats = analyzeJson('{"a": {"b": 1}, "c": [1, 2]}');
      expect(stats.depth).toBeGreaterThan(1);
      expect(stats.hasArrays).toBe(true);
      expect(stats.hasObjects).toBe(true);
    });

    it('should analyze arrays', () => {
      const stats = analyzeJson('[1, 2, 3]');
      expect(stats.hasArrays).toBe(true);
      expect(stats.depth).toBe(1);
    });
  });
});

