/**
 * Format conversion utilities for JSON Tools
 */

/**
 * Converts JSON array of objects to CSV format
 */
export function jsonToCsv(jsonStr: string): string {
  const data = JSON.parse(jsonStr);

  if (!Array.isArray(data) || data.length === 0) {
    throw new Error('Input must be a non-empty JSON array of objects');
  }

  // Get headers from first object
  const headers = Object.keys(data[0]);
  const csv = [
    headers.join(','),
    ...data.map((row: any) =>
      headers
        .map((header) => {
          const value = row[header];
          // Escape quotes and wrap strings
          if (typeof value === 'string' && value.includes(',')) {
            return `"${value.replace(/"/g, '""')}"`;
          }
          return value ?? '';
        })
        .join(',')
    ),
  ].join('\n');

  return csv;
}

/**
 * Converts JSON to simplified YAML format
 */
export function jsonToYaml(jsonStr: string, indent: number = 0): string {
  const data = JSON.parse(jsonStr);
  return yamlStringify(data, indent);
}

function yamlStringify(obj: any, indent: number = 0): string {
  const spaces = ' '.repeat(indent);

  if (obj === null || obj === undefined) {
    return 'null';
  }

  if (typeof obj !== 'object') {
    if (typeof obj === 'string') {
      return `'${obj.replace(/'/g, "''")}'`;
    }
    return String(obj);
  }

  if (Array.isArray(obj)) {
    if (obj.length === 0) return '[]';
    return obj
      .map(
        (item) =>
          `${spaces}- ${
            typeof item === 'object' && item !== null
              ? yamlStringify(item, indent + 2).trim()
              : yamlStringify(item, 0)
          }`
      )
      .join('\n');
  }

  const keys = Object.keys(obj);
  if (keys.length === 0) return '{}';

  return keys
    .map((key) => {
      const value = obj[key];
      const yamlValue = yamlStringify(value, indent + 2);
      if (typeof value === 'object' && value !== null) {
        return `${spaces}${key}:\n${yamlValue}`;
      }
      return `${spaces}${key}: ${yamlValue}`;
    })
    .join('\n');
}

/**
 * Pretty-prints object with custom formatting
 */
export function prettyPrint(jsonStr: string): string {
  const data = JSON.parse(jsonStr);

  function formatValue(value: any, depth: number = 0): string {
    const indent = '  '.repeat(depth);
    const nextIndent = '  '.repeat(depth + 1);

    if (value === null) return 'null';
    if (typeof value !== 'object') return JSON.stringify(value);
    if (Array.isArray(value)) {
      if (value.length === 0) return '[]';
      return (
        '[\n' +
        value
          .map((item) => nextIndent + formatValue(item, depth + 1))
          .join(',\n') +
        '\n' +
        indent +
        ']'
      );
    }

    const keys = Object.keys(value);
    if (keys.length === 0) return '{}';
    return (
      '{\n' +
      keys
        .map(
          (key) =>
            nextIndent +
            JSON.stringify(key) +
            ': ' +
            formatValue(value[key], depth + 1)
        )
        .join(',\n') +
      '\n' +
      indent +
      '}'
    );
  }

  return formatValue(data);
}

