/**
 * Advanced JSON metrics and analysis
 */

export interface DetailedMetrics {
  size: {
    original: number;
    minified: number;
    savings: string;
  };
  structure: {
    objectCount: number;
    arrayCount: number;
    totalElements: number;
    maxDepth: number;
  };
  types: {
    strings: number;
    numbers: number;
    booleans: number;
    nulls: number;
    objects: number;
    arrays: number;
  };
}

export function getDetailedMetrics(jsonStr: string): DetailedMetrics {
  const data = JSON.parse(jsonStr);
  const minified = JSON.stringify(data);

  return {
    size: {
      original: jsonStr.length,
      minified: minified.length,
      savings: (
        (((jsonStr.length - minified.length) / jsonStr.length) * 100).toFixed(
          1
        ) + '%'
      ),
    },
    structure: {
      objectCount: countObjects(data),
      arrayCount: countArrays(data),
      totalElements: countElements(data),
      maxDepth: calculateMaxDepth(data),
    },
    types: countTypes(data),
  };
}

function countObjects(obj: any): number {
  if (typeof obj !== 'object' || obj === null || Array.isArray(obj))
    return 0;

  let count = 1;
  for (const value of Object.values(obj)) {
    if (typeof value === 'object' && value !== null) {
      if (Array.isArray(value)) {
        for (const item of value) {
          count += countObjects(item);
        }
      } else {
        count += countObjects(value);
      }
    }
  }
  return count;
}

function countArrays(obj: any): number {
  if (typeof obj !== 'object' || obj === null) return 0;

  let count = Array.isArray(obj) ? 1 : 0;

  if (Array.isArray(obj)) {
    for (const item of obj) {
      if (typeof item === 'object' && item !== null) {
        count += countArrays(item);
      }
    }
  } else {
    for (const value of Object.values(obj)) {
      if (typeof value === 'object' && value !== null) {
        count += countArrays(value);
      }
    }
  }
  return count;
}

function countElements(obj: any): number {
  if (typeof obj !== 'object' || obj === null) return 0;

  let count = 0;

  if (Array.isArray(obj)) {
    count = obj.length;
    for (const item of obj) {
      if (typeof item === 'object' && item !== null) {
        count += countElements(item);
      }
    }
  } else {
    count = Object.keys(obj).length;
    for (const value of Object.values(obj)) {
      if (typeof value === 'object' && value !== null) {
        count += countElements(value);
      }
    }
  }

  return count;
}

function calculateMaxDepth(obj: any): number {
  if (typeof obj !== 'object' || obj === null) return 0;

  if (Array.isArray(obj)) {
    return obj.length === 0
      ? 1
      : 1 + Math.max(...obj.map(calculateMaxDepth));
  }

  const values = Object.values(obj);
  return values.length === 0 ? 1 : 1 + Math.max(...values.map(calculateMaxDepth));
}

interface TypeCounts {
  strings: number;
  numbers: number;
  booleans: number;
  nulls: number;
  objects: number;
  arrays: number;
}

function countTypes(obj: any): TypeCounts {
  const counts: TypeCounts = {
    strings: 0,
    numbers: 0,
    booleans: 0,
    nulls: 0,
    objects: 0,
    arrays: 0,
  };

  function traverse(value: any): void {
    if (value === null) {
      counts.nulls++;
    } else if (typeof value === 'string') {
      counts.strings++;
    } else if (typeof value === 'number') {
      counts.numbers++;
    } else if (typeof value === 'boolean') {
      counts.booleans++;
    } else if (Array.isArray(value)) {
      counts.arrays++;
      for (const item of value) {
        traverse(item);
      }
    } else if (typeof value === 'object') {
      counts.objects++;
      for (const v of Object.values(value)) {
        traverse(v);
      }
    }
  }

  traverse(obj);
  return counts;
}

